void test() {
    // Test decimalToBinary
    assert(decimalToBinary(10) == "1010");
    assert(decimalToBinary(-5) == "-101");
    assert(decimalToBinary(0) == "0");
    assert(decimalToBinary(255) == "11111111");
    assert(decimalToBinary(-128) == "-10000000");
    assert(decimalToBinary(2147483647) == "1111111111111111111111111111111");

    // Test binaryToDecimal
    assert(binaryToDecimal("1010") == 10);
