    for (const auto& level : result6) {
        for (int val : level) {
            flat_result6.push_back(val);
        }
    }
    vector<int> expected6 = {1, 3, 2, 4, 5, 6};
    assert(flat_result6 == expected6);
    assert(treeHeight(root6) == 4);
    assert(isPerfectTree(root6) == false);
