using namespace std;

void test() {
    // Test case 1: Simple case with 4 points
    {
        vector<pair<int, int>> points = {{1, 1}, {2, 2}, {3, 3}, {4, 4}};
        SpatialAnalyzer analyzer(10);
        auto levels = analyzer.countLevels(points);
        map<int, int> expected_levels = {{0, 1}, {1, 1}, {2, 1}, {3, 1}};
        assert(levels == expected_levels);
        assert(analyzer.rangeQuery(points, 1, 3, 1, 3) == 3);
        assert(analyzer.countDominatingPoints(points, 2, 2) == 0);
    }

    // Test case 2: Points with same x-coordinate
    {
        vector<pair<int, int>> points = {{1, 5}, {1, 4}, {1, 3}, {1, 2}};
        SpatialAnalyzer analyzer(10);
        auto levels = analyzer.countLevels(points);
        map<int, int> expected_levels = {{0, 1}, {1, 1}, {2, 1}, {3, 1}};
        assert(levels == expected_levels);
    }

    // Test case 3: Empty input
    {
        vector<pair<int, int>> points;
        SpatialAnalyzer analyzer(10);
        auto levels = analyzer.countLevels(points);
        assert(levels.empty());
    }

    // Test case 4: Large coordinates
    {
        vector<pair<int, int>> points = {{10000, 10000}, {20000, 20000}, {30000, 30000}};
        SpatialAnalyzer analyzer(35000);
        auto levels = analyzer.countLevels(points);
        map<int, int> expected_levels = {{0, 1}, {1, 1}, {2, 1}};
        assert(levels == expected_levels);
    }

    // Test case 5: Randomly distributed points
    {
        vector<pair<int, int>> points = {{3, 6}, {7, 1}, {2, 8}, {5, 4}, {9, 2}};
        SpatialAnalyzer analyzer(10);
        auto levels = analyzer.countLevels(points);
