    assert(analyzer.findLongestCommonSubsequence(str1, str2) == "BABC");

    // Test case 3: No common substring
    str1 = "ABCDEF";
    str2 = "GHIJKL";
    assert(analyzer.findLongestCommonSubstring(str1, str2) == "");
    assert(analyzer.findLongestCommonSubsequence(str1, str2) == "");

    // Test case 4: Empty strings
