    assert(analyzer.findLongestCommonSubstring(str1, str2) == "你好");
    assert(analyzer.findLongestCommonSubsequence(str1, str2) == "世界h");

    // Test case 8: Complete match
    str1 = "identical";
    str2 = "identical";
    assert(analyzer.findLongestCommonSubstring(str1, str2) == "identical");
    assert(analyzer.findLongestCommonSubsequence(str1, str2) == "identical");
}

