#include <cassert>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>

using namespace std;

void test() {
    // Test Case 1: Two spheres not colliding
    {
        CollisionSphere sphere1(Vector3(0, 0, 0), 1.0f);
        CollisionSphere sphere2(Vector3(3, 0, 0), 1.0f);
        CollisionData data;
        assert(!SphereSphereCollision(sphere1, sphere2, data));
    }

    // Test Case 2: Two spheres colliding
    {
        CollisionSphere sphere1(Vector3(0, 0, 0), 1.0f);
        CollisionSphere sphere2(Vector3(1.5f, 0, 0), 1.0f);
        CollisionData data;
        assert(SphereSphereCollision(sphere1, sphere2, data));
        assert(fabs(data.penetration - 0.5f) < numeric_limits<float>::epsilon());
    }

    // Test Case 3: Sphere and AABB not colliding
    {
        CollisionSphere sphere(Vector3(0, 0, 0), 1.0f);
        CollisionAABB aabb(Vector3(3, 0, 0), Vector3(1, 1, 1));
        CollisionData data;
        assert(!SphereAABBCollision(sphere, aabb, data));
    }

    // Test Case 4: Sphere and AABB colliding
    {
        CollisionSphere sphere(Vector3(2, 0, 0), 1.0f);
        CollisionAABB aabb(Vector3(3.5f, 0, 0), Vector3(1, 1, 1));
        CollisionData data;
        assert(SphereAABBCollision(sphere, aabb, data));
        assert(fabs(data.penetration - 0.5f) < numeric_limits<float>::epsilon());
    }

    // Test Case 5: Edge case - sphere exactly touching AABB
    {
        CollisionSphere sphere(Vector3(2, 0, 0), 1.0f);
        CollisionAABB aabb(Vector3(3, 0, 0), Vector3(1, 1, 1));
        CollisionData data;
        assert(SphereAABBCollision(sphere, aabb, data));
    }

    // Test Case 6: GJK test - two AABBs colliding
    {
        CollisionAABB aabb1(Vector3(0, 0, 0), Vector3(1, 1, 1));
        CollisionAABB aabb2(Vector3(1.5f, 0, 0), Vector3(1, 1, 1));
        CollisionData data;
        data.shapeA = &aabb1;
        data.shapeB = &aabb2;
        assert(!GJKCollision(aabb1, aabb2, data));
    }

    // Test Case 7: GJK test - two AABBs not colliding
    {
        CollisionAABB aabb1(Vector3(0, 0, 0), Vector3(1, 1, 1));
        CollisionAABB aabb2(Vector3(3, 0, 0), Vector3(1, 1, 1));
        CollisionData data;
        assert(!GJKCollision(aabb1, aabb2, data));
    }

    // Test Case 8: Collision response test
    {
        CollisionSphere sphere1(Vector3(0, 0, 0), 1.0f);
        CollisionSphere sphere2(Vector3(1.5f, 0, 0), 1.0f);
        sphere1.velocity = Vector3(2, 0, 0);
        sphere2.velocity = Vector3(-1, 0, 0);

        CollisionData data;
        data.shapeA = &sphere1;
        data.shapeB = &sphere2;

        if (SphereSphereCollision(sphere1, sphere2, data)) {
            data.ResolveCollision();
            assert(fabs(sphere1.velocity.x - (-0.7f)) < 0.1f);
            assert(fabs(sphere2.velocity.x - 1.7f) < 0.1f);
            assert(fabs(sphere1.velocity.y) < numeric_limits<float>::epsilon());
            assert(fabs(sphere2.velocity.y) < numeric_limits<float>::epsilon());
            assert(fabs(sphere1.velocity.z) < numeric_limits<float>::epsilon());
            assert(fabs(sphere2.velocity.z) < numeric_limits<float>::epsilon());
        }
    }
}

int main() {
    test();
    return 0;
}

