    err2.add_context("Expected: int");
    err2.add_context("Found: string");
    assert(err2.format() == "[line: 20, error: 200, severity: ERROR, category: SEMANTIC] Type mismatch\nContext:\n  - Expected: int\n  - Found: string");

    // Test case 3: Warning
    Error err3(300, "Unused variable", 5, ErrorSeverity::WARNING);
    assert(err3.format() == "[line: 5, error: 300, severity: WARNING, category: SYNTAX] Unused variable");

    // Test case 4: Critical error
    Error err4(400, "File not found", 1, ErrorSeverity::CRITICAL, ErrorCategory::SYSTEM);
    assert(err4.format() == "[line: 1, error: 400, severity: CRITICAL, category: SYSTEM] File not found");

    // Test case 5: Info message
    Error err5(500, "Using deprecated function", 30, ErrorSeverity::INFO);
    assert(err5.format() == "[line: 30, error: 500, severity: INFO, category: SYNTAX] Using deprecated function");

    // Test case 6: Error with same line number but different severity
    Error err6(600, "Network timeout", 42, ErrorSeverity::ERROR, ErrorCategory::NETWORK);
    Error err7(601, "Fallback to local cache", 42, ErrorSeverity::WARNING);
    assert(err6.format() == "[line: 42, error: 600, severity: ERROR, category: NETWORK] Network timeout");
    assert(err7.format() == "[line: 42, error: 601, severity: WARNING, category: SYNTAX] Fallback to local cache");

    // Test case 7: Error manager functionality
    ErrorManager manager;
    manager.add_error(err1);
    manager.add_error(err2);
    manager.add_error(err3);
    manager.add_error(err4);
    manager.add_error(err5);
    manager.add_error(err6);
    manager.add_error(err7);

    auto sorted_errors = manager.get_sorted_errors();
    assert(sorted_errors.size() == 7);
    assert(sorted_errors[0].get_line() == 1);
    assert(sorted_errors[1].get_line() == 5);
    assert(sorted_errors[2].get_line() == 10);
    assert(sorted_errors[3].get_line() == 20);
    assert(sorted_errors[4].get_line() == 30);
    assert(sorted_errors[5].get_line() == 42);
    assert(sorted_errors[6].get_line() == 42);

    assert(manager.get_error_description(101) == "Missing semicolon");
    assert(manager.get_error_description(999) == "Unknown error");
    assert(manager.has_serious_errors() == true);
