#include <cassert>
#include <vector>
#include <cmath>
#include <stdexcept>

using namespace std;

void test() {
    // Test Case 1: Basic Square Sprite
    {
        Sprite3D sprite1;
        sprite1.moveTo(0, 0, -5);
        vector<Vector4> screenVerts1 = sprite1.getScreenVertices();
        assert(fabs(screenVerts1[0].x - (-0.241422f)) < 1e-5f);
        assert(fabs(screenVerts1[0].y - 0.241422f) < 1e-5f);
        assert(fabs(screenVerts1[0].z - 0.961962f) < 1e-5f);
        assert(fabs(screenVerts1[3].x - 0.241422f) < 1e-5f);
        assert(fabs(screenVerts1[3].y - 0.241422f) < 1e-5f);
        assert(fabs(screenVerts1[3].z - 0.961962f) < 1e-5f);
        assert(sprite1.isFacingCamera() == true);
        assert(fabs(sprite1.calculateArea() - 0.5f) < 1e-5f);
    }

    // Test Case 2: Rotated Sprite
    {
        Sprite3D sprite2;
        sprite2.moveTo(0, 0, -5);
        sprite2.rotate(0.785f, 0, 0);
        vector<Vector4> screenVerts2 = sprite2.getScreenVertices();
        assert(fabs(screenVerts2[0].x - (-0.259784f)) < 1e-5f);
        assert(fabs(screenVerts2[0].y - 0.183768f) < 1e-5f);
        assert(fabs(screenVerts2[3].x - 0.259784f) < 1e-5f);
        assert(fabs(screenVerts2[3].y - 0.183768f) < 1e-5f);
        assert(sprite2.isFacingCamera() == true);
        assert(fabs(sprite2.calculateArea() - 0.5f) < 1e-5f);
    }

    // Test Case 3: Distant Sprite
    {
        Sprite3D sprite3;
        sprite3.moveTo(0, 0, -20);
        vector<Vector4> screenVerts3 = sprite3.getScreenVertices();
        assert(fabs(screenVerts3[0].x - (-0.0603554f)) < 1e-5f);
        assert(fabs(screenVerts3[0].y - 0.0603554f) < 1e-5f);
        assert(fabs(screenVerts3[0].z - 0.991992f) < 1e-5f);
        assert(sprite3.isFacingCamera() == true);
        assert(fabs(sprite3.calculateArea() - 0.5f) < 1e-5f);
    }

    // Test Case 4: Back-facing Sprite
    {
        Sprite3D sprite4;
        sprite4.moveTo(0, 0, -5);
        sprite4.rotate(0, 3.14159f, 0);
        vector<Vector4> screenVerts4 = sprite4.getScreenVertices();
        assert(fabs(screenVerts4[0].x - 0.241422f) < 1e-5f);
        assert(fabs(screenVerts4[0].y - 0.241422f) < 1e-5f);
        assert(fabs(screenVerts4[0].z - 0.961962f) < 1e-5f);
        assert(sprite4.isFacingCamera() == false);
        assert(fabs(sprite4.calculateArea() - 0.5f) < 1e-5f);
    }

    // Test Case 5: Colored Sprite
    {
        Sprite3D sprite5;
        sprite5.moveTo(0, 0, -5);
        vector<Vector4> screenVerts5 = sprite5.getScreenVertices();
        assert(fabs(screenVerts5[0].x - (-0.241422f)) < 1e-5f);
        assert(fabs(screenVerts5[0].y - 0.241422f) < 1e-5f);
        assert(sprite5.isFacingCamera() == true);
        assert(fabs(sprite5.calculateArea() - 0.5f) < 1e-5f);
    }

    // Test Case 6: Rectangle Sprite
    {
        Sprite3D sprite6(
            Vector4(-1, 0.5f, 0),
            Vector4(-1, -0.5f, 0),
            Vector4(1, -0.5f, 0),
            Vector4(1, 0.5f, 0)
        );
        sprite6.moveTo(0, 0, -5);
        vector<Vector4> screenVerts6 = sprite6.getScreenVertices();
        assert(fabs(screenVerts6[0].x - (-0.482843f)) < 1e-5f);
        assert(fabs(screenVerts6[0].y - 0.241422f) < 1e-5f);
        assert(fabs(screenVerts6[3].x - 0.482843f) < 1e-5f);
        assert(fabs(screenVerts6[3].y - 0.241422f) < 1e-5f);
        assert(sprite6.isFacingCamera() == true);
        assert(fabs(sprite6.calculateArea() - 1.0f) < 1e-5f);
    }

    // Test Case 7: Complex Transformation
    {
        Sprite3D sprite7;
        sprite7.moveTo(1, 0.5f, -8);
        sprite7.rotate(0.5f, 0.3f, 0.2f);
        vector<Vector4> screenVerts7 = sprite7.getScreenVertices();
        assert(fabs(screenVerts7[0].x - 0.137719f) < 1e-5f);
        assert(fabs(screenVerts7[0].y - 0.239337f) < 1e-5f);
        assert(fabs(screenVerts7[0].z - 0.975866f) < 1e-5f);
        assert(sprite7.isFacingCamera() == true);
        assert(fabs(sprite7.calculateArea() - 0.5f) < 1e-5f);
    }

    // Test Case 8: Edge Position
    {
        Sprite3D sprite8;
        sprite8.moveTo(3, 2, -5);
        vector<Vector4> screenVerts8 = sprite8.getScreenVertices();
        assert(fabs(screenVerts8[0].x - 1.20711f) < 1e-5f);
        assert(fabs(screenVerts8[0].y - 1.20711f) < 1e-5f);
        assert(fabs(screenVerts8[0].z - 0.961962f) < 1e-5f);
        assert(sprite8.isFacingCamera() == true);
        assert(fabs(sprite8.calculateArea() - 0.5f) < 1e-5f);
    }
}

int main() {
    test();
    return 0;
}

