#include <cassert>
#include <vector>
#include <string>
#include <memory>
#include <stdexcept>
#include <map>

using namespace std;

void test() {
    // Test Case 1: Basic weapon
    Weapon dagger("Iron Dagger", 5, 100, 15, "Piercing");
    assert(dagger.getName() == "Iron Dagger");
    assert(dagger.getType() == "Weapon");
    assert(dagger.getWeight() == 5);
    assert(dagger.getCondition() == 100);
    assert(dagger.getMaxCondition() == 100);
    assert(dagger.calculateValue() == 650);
    assert(dagger.isEnchanted() == false);
    assert(dagger.getEnchantments().size() == 0);

    // Test Case 2: Enchanted weapon
    Weapon greatsword("Greatsword", 30, 90, 40, "Slashing");
    FrostEnchant* frostEnchant = new FrostEnchant(5);
    greatsword.addEnchantment(frostEnchant);
    assert(greatsword.getName() == "Greatsword");
    assert(greatsword.getType() == "Weapon");
    assert(greatsword.getWeight() == 30);
    assert(greatsword.getCondition() == 90);
    assert(greatsword.getMaxCondition() == 90);
    assert(greatsword.calculateValue() == 950);
    assert(greatsword.isEnchanted() == true);
    assert(greatsword.getEnchantments().size() == 1);
    assert(greatsword.getEnchantments()[0]->getName() == "Frost Enchant");
    assert(greatsword.getEnchantments()[0]->getPower() == 5);
    assert(greatsword.getEnchantments()[0]->getEffect() == "Slows enemies on hit");

    // Test Case 3: Damaged armor
    Armor helmet("Steel Helmet", 10, 45, 15, "Heavy");
    assert(helmet.getName() == "Steel Helmet");
    assert(helmet.getType() == "Armor");
    assert(helmet.getWeight() == 10);
    assert(helmet.getCondition() == 45);
    assert(helmet.getMaxCondition() == 45);
    assert(helmet.calculateValue() == 450);
    assert(helmet.isEnchanted() == false);
    assert(helmet.getEnchantments().size() == 0);

    // Test Case 4: Repaired armor
    helmet.repair(30);
    assert(helmet.getCondition() == 45);  // Shouldn't exceed max condition
    assert(helmet.calculateValue() == 450);

    // Test Case 5: Double-enchanted weapon
    Weapon bow("Longbow", 10, 100, 20, "Piercing");
    FireEnchant* fire1 = new FireEnchant(2);
    FrostEnchant* frost1 = new FrostEnchant(3);
    bow.addEnchantment(fire1);
    bow.addEnchantment(frost1);
    assert(bow.getName() == "Longbow");
    assert(bow.getType() == "Weapon");
    assert(bow.getWeight() == 10);
    assert(bow.getCondition() == 100);
    assert(bow.getMaxCondition() == 100);
    assert(bow.calculateValue() == 800);
    assert(bow.isEnchanted() == true);
    assert(bow.getEnchantments().size() == 2);
    assert(bow.getEnchantments()[0]->getName() == "Fire Enchant");
    assert(bow.getEnchantments()[1]->getName() == "Frost Enchant");

    // Test Case 6: Light armor
    Armor leather("Leather Armor", 5, 100, 10, "Light");
    assert(leather.getName() == "Leather Armor");
    assert(leather.getType() == "Armor");
    assert(leather.getWeight() == 5);
    assert(leather.getCondition() == 100);
    assert(leather.getMaxCondition() == 100);
    assert(leather.calculateValue() == 650);
    assert(leather.isEnchanted() == false);

    // Test Case 7: Broken equipment
    Weapon axe("Battle Axe", 25, 0, 35, "Slashing");
    assert(axe.getName() == "Battle Axe");
    assert(axe.getType() == "Weapon");
    assert(axe.getWeight() == 25);
    assert(axe.getCondition() == 0);
    assert(axe.getMaxCondition() == 0);
    assert(axe.calculateValue() == 350);
    assert(axe.isEnchanted() == false);

    // Test Case 8: Fully repaired and enchanted armor
    Armor shield("Tower Shield", 20, 100, 40, "Heavy");
    FireEnchant* fireShield = new FireEnchant(4);
    shield.addEnchantment(fireShield);
    assert(shield.getName() == "Tower Shield");
    assert(shield.getType() == "Armor");
    assert(shield.getWeight() == 20);
    assert(shield.getCondition() == 100);
    assert(shield.getMaxCondition() == 100);
    assert(shield.calculateValue() == 1200);
    assert(shield.isEnchanted() == true);
    assert(shield.getEnchantments().size() == 1);
    assert(shield.getEnchantments()[0]->getName() == "Fire Enchant");
    assert(shield.getEnchantments()[0]->getPower() == 4);
}

int main() {
    test();
    return 0;
}

