#include <cassert>
#include <cmath>
#include <iostream>
using namespace std;

void test() {
    // Test case 1: Default camera
    {
        Camera cam;
        assert(cam.GetPos().x == 0 && cam.GetPos().y == 0 && cam.GetPos().z == 0);
        assert(cam.GetRotator().x == 0 && cam.GetRotator().y == 0 && cam.GetRotator().z == 0);
        assert(abs(cam.GetForwardVector().x - 1) < 1e-5 && abs(cam.GetForwardVector().y) < 1e-5 && abs(cam.GetForwardVector().z) < 1e-5);
        assert(abs(cam.GetUpVector().x) < 1e-5 && abs(cam.GetUpVector().y - 1) < 1e-5 && abs(cam.GetUpVector().z) < 1e-5);
        assert(abs(cam.GetRightSideVector().x) < 1e-5 && abs(cam.GetRightSideVector().y) < 1e-5 && abs(cam.GetRightSideVector().z - 1) < 1e-5);
        assert(cam.IsAABBInside(AABB(Vector(0,0,0), Vector(0,0,0))) == true);
    }

    // Test case 2: Camera looking straight down
    {
        Camera cam("TopDown", Vector(0, 10, 0), Vector(-90, 0, 0));
        assert(cam.GetPos().x == 0 && cam.GetPos().y == 10 && cam.GetPos().z == 0);
        assert(abs(cam.GetForwardVector().x) < 1e-5 && abs(cam.GetForwardVector().y + 1) < 1e-5 && abs(cam.GetForwardVector().z) < 1e-5);
        assert(cam.IsAABBInside(AABB(Vector(0,0,0), Vector(0,0,0))) == true);
    }

    // Test case 3: Camera with narrow FOV
    {
        Camera cam("NarrowFOV", Vector(0,0,-5), Vector(), 30.0f);
        assert(cam.IsAABBInside(AABB(Vector(-10,-10,-1), Vector(10,10,-1))) == true);
    }

    // Test case 4: Camera with very near clip plane
    {
        Camera cam("NearClip", Vector(0,0,5), Vector(0,180,0), 60.0f, 100.0f, 0.01f);
        assert(cam.IsAABBInside(AABB(Vector(0,0,5), Vector(0,0,5))) == true);
    }

    // Test case 5: Camera with roll
    {
        Camera cam("Rolled", Vector(5,1,5), Vector(0,45,30));
        assert(cam.IsAABBInside(AABB(Vector(6,1,6), Vector(6,1,6))) == true);
    }

    // Test case 6: High-resolution camera
    {
        Camera cam("4K", Vector(-2,3,1), Vector(20,-30,0), 90.0f, 1000.0f, 0.1f, 3840.0f, 2160.0f);
        assert(cam.IsAABBInside(AABB(Vector(-5,-5,-5), Vector(5,5,5))) == true);
    }

    // Test case 7: Camera at world origin
    {
        Camera cam("Origin", Vector(), Vector(0,45,0));
        assert(cam.IsAABBInside(AABB(Vector(0,0,1), Vector(0,0,1))) == true);
    }

    // Test case 8: Camera with extreme rotation
    {
        Camera cam("Extreme", Vector(100,50,-30), Vector(89,180,89));
        assert(cam.IsAABBInside(AABB(Vector(100,50,-1030), Vector(100,50,-1030))) == false);
    }
}

int main() {
    test();
    return 0;
}

