        assert(agency.countObservers() == 3);
        for (auto& channel : channels) {
            assert(channel.getLatestNews() == "BREAKING: News for all channels");
        }
    }

    // Test case 3: Remove observer
    {
        NewsAgency agency;
        NewsChannel channelA("Channel A");
        NewsChannel channelB("Channel B");

        agency.addObserver(&channelA);
        agency.addObserver(&channelB);
        agency.publishNews("Initial news");
        agency.removeObserver(&channelA);
        agency.publishNews("After removal");

        assert(agency.countObservers() == 1);
        assert(channelA.newsCount() == 1);
        assert(channelB.newsCount() == 2);
    }

    // Test case 4: No observers
    {
        NewsAgency agency;
        agency.publishNews("News with no observers");

        assert(agency.getState() == "BREAKING: News with no observers");
        assert(agency.countObservers() == 0);
    }

    // Test case 5: Multiple notifications
    {
        NewsAgency agency;
        NewsChannel channel("Multi-news Channel");
        agency.addObserver(&channel);

        for (int i = 1; i <= 5; i++) {
            agency.publishNews("Update " + std::to_string(i));
        }

        assert(channel.newsCount() == 5);
        assert(channel.getLatestNews() == "BREAKING: Update 5");
    }

    // Test case 6: Null observer
    {
        NewsAgency agency;
        agency.addObserver(nullptr);
        agency.publishNews("Test null observer");

        assert(agency.countObservers() == 0);
    }

    // Test case 7: Observer state clearing
    {
        NewsAgency agency;
        NewsChannel channel("Clear Test");
        agency.addObserver(&channel);
        agency.publishNews("First message");
        channel.clearNews();
        agency.publishNews("Second message");

        assert(channel.newsCount() == 1);
        assert(channel.getLatestNews() == "BREAKING: Second message");
    }
}

int main() {
    test();
    return 0;
}

