        assert(words.size() == 1);
        assert(words[0].first == "hello" && words[0].second == 1);
    }

    // Test Case 3: Multiple words with duplicates
    {
        Tree tree;
        tree.Add("apple");
        tree.Add("banana");
        tree.Add("apple");
        tree.Add("cherry");
        tree.Add("banana");
        tree.Add("apple");
        assert(tree.getTotalWordCount() == 6);
        assert(tree.getDistinctWordCount() == 3);
        assert(tree.getWordCount("apple") == 3);
        assert(tree.getWordCount("banana") == 2);
        assert(tree.getWordCount("cherry") == 1);
    }

    // Test Case 4: Removing words
    {
        Tree tree;
        tree.Add("one");
        tree.Add("two");
        tree.Add("three");
        tree.Add("two");
        tree.Add("one");
        assert(tree.getTotalWordCount() == 5);
        assert(tree.getDistinctWordCount() == 3);
        assert(tree.getWordCount("one") == 2);
        assert(tree.getWordCount("two") == 2);
        assert(tree.getWordCount("three") == 1);

        tree.Remove("two");
        assert(tree.getTotalWordCount() == 4);
        assert(tree.getDistinctWordCount() == 3);
        assert(tree.getWordCount("two") == 1);

        tree.Remove("one");
        assert(tree.getTotalWordCount() == 3);
        assert(tree.getDistinctWordCount() == 3);
        assert(tree.getWordCount("one") == 1);
    }

    // Test Case 5: Case sensitivity
    {
        Tree tree;
        tree.Add("Word");
        tree.Add("word");
        tree.Add("WORD");
        assert(tree.getTotalWordCount() == 3);
        assert(tree.getDistinctWordCount() == 3);
        assert(tree.getWordCount("Word") == 1);
        assert(tree.getWordCount("word") == 1);
        assert(tree.getWordCount("WORD") == 1);
    }

    // Test Case 6: Large number of words
    {
        Tree tree;
        string words[] = {"the", "quick", "brown", "fox", "jumps", "over", "the", "lazy", "dog"};
        for (int i = 0; i < 50; i++) {
            tree.Add(words[i % 9]);
        }
        assert(tree.getTotalWordCount() == 50);
        assert(tree.getDistinctWordCount() == 8);
        assert(tree.getWordCount("the") == 11);
        assert(tree.getWordCount("quick") == 6);
        assert(tree.getWordCount("brown") == 6);
        assert(tree.getWordCount("fox") == 6);
        assert(tree.getWordCount("jumps") == 6);
        assert(tree.getWordCount("over") == 5);
        assert(tree.getWordCount("lazy") == 5);
        assert(tree.getWordCount("dog") == 5);
    }

    // Test Case 7: Most frequent words
    {
        Tree tree;
        tree.Add("a");
        tree.Add("b"); tree.Add("b");
        tree.Add("c"); tree.Add("c"); tree.Add("c");
        tree.Add("d"); tree.Add("d"); tree.Add("d"); tree.Add("d");
        tree.Add("e"); tree.Add("e"); tree.Add("e"); tree.Add("e"); tree.Add("e");

        vector<string> topWords = tree.getMostFrequentWords(3);
        assert(topWords.size() == 3);
        assert(topWords[0] == "e");
        assert(topWords[1] == "d");
        assert(topWords[2] == "c");
        assert(tree.getWordCount(topWords[0]) == 5);
        assert(tree.getWordCount(topWords[1]) == 4);
        assert(tree.getWordCount(topWords[2]) == 3);
    }

    // Test Case 8: Words by frequency
    {
        Tree tree;
        tree.Add("apple");
        tree.Add("banana"); tree.Add("banana");
        tree.Add("cherry"); tree.Add("cherry"); tree.Add("cherry");
        tree.Add("date"); tree.Add("date"); tree.Add("date"); tree.Add("date");

        map<int, vector<string>> freqMap = tree.getWordsByFrequency();
        assert(freqMap.size() == 4);
        assert(freqMap[1].size() == 1 && freqMap[1][0] == "apple");
        assert(freqMap[2].size() == 1 && freqMap[2][0] == "banana");
        assert(freqMap[3].size() == 1 && freqMap[3][0] == "cherry");
        assert(freqMap[4].size() == 1 && freqMap[4][0] == "date");
    }
}

int main() {
    test();
    return 0;
}

