    {
        RobotLocalization rl({0, 0, 0});
        rl.predict(0.0, M_PI/2, 1000);
        auto pose = rl.getPose();
        assert(abs(pose[0] - 0.0) < 1e-6);
        assert(abs(pose[1] - 0.0) < 1e-6);
        assert(abs(pose[2] - 1.5708) < 1e-4);
    }

