        rl.predict(1.0, M_PI/4, 1000);
        auto pose = rl.getPose();
        assert(abs(pose[0] - 1.0) < 1e-6);
        assert(abs(pose[1] - 0.0) < 1e-6);
        assert(abs(pose[2] - 0.785398) < 1e-6);
    }

    // Test Case 5: Perfect landmark update
    {
        RobotLocalization rl({1, 1, M_PI/4});
        rl.updateLandmark(sqrt(2), 0.0, 2.0, 2.0);
        auto pose = rl.getPose();
        assert(abs(pose[0] - 1.0) < 1e-6);
        assert(abs(pose[1] - 1.0) < 1e-6);
        assert(abs(pose[2] - 0.785398) < 1e-6);
    }

    // Test Case 6: Noisy landmark update
    {
        RobotLocalization rl({1.1, 0.9, M_PI/4 + 0.1});
        rl.updateLandmark(sqrt(2), 0.0, 2.0, 2.0);
        auto pose = rl.getPose();
        assert(abs(pose[0] - 1.10011) < 1e-5);
        assert(abs(pose[1] - 0.899907) < 1e-5);
        assert(abs(pose[2] - 0.88519) < 1e-5);
    }

    // Test Case 7: Full sequence
    {
        RobotLocalization rl({0, 0, 0});
        rl.predict(1.0, 0.0, 1000);
        assert(abs(rl.getPose()[0] - 1.0) < 1e-6);

        rl.updateLandmark(1.0, 0.0, 2.0, 0.0);
        assert(abs(rl.getPose()[0] - 1.0) < 1e-6);

        rl.predict(0.5, M_PI/2, 1000);
        assert(abs(rl.getPose()[2] - 1.5708) < 1e-4);

        rl.updateLandmark(1.0, -M_PI/2, 1.0, 2.0);
        assert(abs(rl.getPose()[0] - 0.0192169) < 1e-6);
        assert(abs(rl.getPose()[1] - (-0.27463)) < 1e-5);
    }

    // Test Case 8: Large angle normalization
    {
        RobotLocalization rl({0, 0, 3*M_PI});
        auto pose = rl.getPose();
        assert(abs(pose[2] - M_PI) < 1e-6);
    }
}

int main() {
    test();
    return 0;
}

