#include <cassert>
#include <cmath>
#include <iomanip>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

void test() {
    // Set global time to 10.0 hours for all tests
    Fahrzeug::vSetzeGlobaleZeit(10.0);

    // Test case 1: Basic vehicle with fuel
    Fahrzeug v1("Auto1", 120.0, 50.0, 6.5);
    v1.vAbfertigung();
    assert(v1.getID() == 1);
    assert(v1.getName() == "Auto1");
    assert(fabs(v1.getMaxSpeed() - 120.0) < 1e-9);
    assert(fabs(v1.getTotalDistance() - 769.23) < 0.01);
    assert(fabs(v1.getFuelLevel() - 0.0) < 1e-9);
    assert(v1.isParked() == true);

    // Test case 2: Vehicle assignment and comparison
    Fahrzeug v2 = v1;
    v2.vAbfertigung();
    assert(v2.getID() == 2);
    assert(v2.getName() == "Auto1'");
    assert(fabs(v2.getMaxSpeed() - 120.0) < 1e-9);
    assert(fabs(v2.getTotalDistance() - 0.0) < 1e-9);
    assert(fabs(v2.getFuelLevel() - 0.0) < 1e-9);
    assert(v2.isParked() == true);
    assert((v1 < v2) == false);

    // Test case 3: Empty vehicle (no fuel)
    Fahrzeug v3("Auto3", 100.0, 0.0, 5.0);
    v3.vAbfertigung();
    assert(v3.getID() == 3);
    assert(v3.getName() == "Auto3");
    assert(fabs(v3.getMaxSpeed() - 100.0) < 1e-9);
    assert(fabs(v3.getTotalDistance() - 0.0) < 1e-9);
    assert(fabs(v3.getFuelLevel() - 0.0) < 1e-9);
    assert(v3.isParked() == true);

    // Test case 4: Parked vehicle
    Fahrzeug v4("Auto4", 90.0, 40.0, 7.0);
    v4.vParken();
    v4.vAbfertigung();
    assert(v4.getID() == 4);
    assert(v4.getName() == "Auto4");
    assert(fabs(v4.getMaxSpeed() - 90.0) < 1e-9);
    assert(fabs(v4.getTotalDistance() - 0.0) < 1e-9);
    assert(fabs(v4.getFuelLevel() - 40.0) < 1e-9);
    assert(v4.isParked() == true);

    // Test case 5: Refueling test
    Fahrzeug v5("Auto5", 80.0, 30.0, 6.0);
    v5.vAbfertigung();
    double fuelAdded = v5.dTanken(20.0);
    assert(v5.getID() == 5);
    assert(v5.getName() == "Auto5");
    assert(fabs(v5.getMaxSpeed() - 80.0) < 1e-9);
    assert(fabs(v5.getTotalDistance() - 500.0) < 0.1);
    assert(fabs(v5.getFuelLevel() - 20.0) < 1e-9);
    assert(v5.isParked() == false);
    assert(fabs(fuelAdded - 20.0) < 1e-9);

    // Test case 6: Vehicle running out of fuel
    Fahrzeug v6("Auto6", 70.0, 5.0, 8.0);
    v6.vAbfertigung();
    v6.vAbfertigung();
    assert(v6.getID() == 6);
    assert(v6.getName() == "Auto6");
    assert(fabs(v6.getMaxSpeed() - 70.0) < 1e-9);
    assert(fabs(v6.getTotalDistance() - 62.5) < 0.1);
    assert(fabs(v6.getFuelLevel() - 0.0) < 1e-9);
    assert(v6.isParked() == true);

    // Test case 7: Multiple time updates
    Fahrzeug::vSetzeGlobaleZeit(5.0);
    Fahrzeug v7("Auto7", 60.0, 45.0, 5.5);
    v7.vAbfertigung();
    Fahrzeug::vSetzeGlobaleZeit(15.0);
    v7.vAbfertigung();
    assert(v7.getID() == 7);
    assert(v7.getName() == "Auto7");
    assert(fabs(v7.getMaxSpeed() - 60.0) < 1e-9);
    assert(fabs(v7.getTotalDistance() - 818.18) < 0.1);
    assert(fabs(v7.getFuelLevel() - 0.0) < 1e-9);
    assert(v7.isParked() == true);
    assert(fabs(v7.dVerbrauchBerechnen() - 45.0) < 0.1);

    // Test case 8: Vehicle comparison
    Fahrzeug v8a("Auto8a", 110.0, 60.0, 6.0);
    Fahrzeug v8b("Auto8b", 110.0, 60.0, 6.0);
    v8a.vAbfertigung();
    Fahrzeug::vSetzeGlobaleZeit(20.0);
    v8b.vAbfertigung();
    assert(v8a.getID() == 8);
    assert(v8a.getName() == "Auto8a");
    assert(fabs(v8a.getMaxSpeed() - 110.0) < 1e-9);
    assert(fabs(v8a.getTotalDistance() - 1000.0) < 0.1);
    assert(fabs(v8a.getFuelLevel() - 0.0) < 1e-9);
    assert(v8a.isParked() == true);

    assert(v8b.getID() == 9);
    assert(v8b.getName() == "Auto8b");
    assert(fabs(v8b.getMaxSpeed() - 110.0) < 1e-9);
    assert(fabs(v8b.getTotalDistance() - 1000.0) < 0.1);
    assert(fabs(v8b.getFuelLevel() - 0.0) < 1e-9);
    assert(v8b.isParked() == true);
    assert((v8a < v8b) == false);
}

int main() {
    test();
    return 0;
}

