        vector<int> expected = {2, 2, 2, 2, 2, 2, 2, 2, 3, 3};
        assert(build_advanced_wall(n, ops, lefts, rights, heights) == expected);
    }

    // Test Case 7: Edge case with minimum and maximum values
    {
        int n = 4;
        vector<int> ops = {1, 2};
        vector<int> lefts = {0, 2};
        vector<int> rights = {3, 3};
        vector<int> heights = {INT_MAX, INT_MIN};
        vector<int> expected = {INT_MAX, INT_MAX, INT_MIN, INT_MIN};
        assert(build_advanced_wall(n, ops, lefts, rights, heights) == expected);
    }
}

